"""Report transplanted seed identity, fresh-epoch cost and flood ablations."""
import csv,json,hashlib,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];P=ROOT/'tests/diagnostics/results/recal2026/seed-index-port-20261013';B=P.parent/'correction-accuracy-cost-20261013'
def main():
 a=list(csv.DictReader((P/'seeds-before.tsv').open(),delimiter='\t'));b=list(csv.DictReader((P/'seeds-final.tsv').open(),delimiter='\t'))
 mismatches=[(x['id'],f) for x,y in zip(a,b) for f in ['id','support','nseeds','coordinates'] if x[f]!=y[f]]
 if len(a)!=7216 or len(b)!=7216 or mismatches:raise RuntimeError('Seed identity validation failed')
 seed=json.loads((P/'timing-summary.json').read_text());full=json.loads((P/'full-summary.json').read_text());inputs={str(i['sample_id']):i for i in json.loads((B/'inputs.json').read_text())};raw=list(csv.DictReader((P/'phase-after.tsv').open(),delimiter='\t'));flood=[]
 for profile in ['uniform','linear']:
  for tol in ['0.001','0.0001']:
   rs=[r for r in raw if r['trace']=='1' and r['repeat']=='1' and inputs[r['sample_id']]['profile']==profile and r['target']==tol]
   duration=sum(float(r['initial_fill_ms'])+float(r['additional_fill_ms']) for r in rs)
   flood.append(dict(profile=profile,target=tol,boundary_fraction_of_fill=sum(float(r['row_boundary_ms']) for r in rs)/duration,queries=sum(int(r['fill_queries']) for r in rs),cells=sum(int(r['fill_cells']) for r in rs),rows=sum(int(r['fill_rows']) for r in rs),new_maps=sum(int(r['maps']) for r in rs),reused_maps=sum(int(r['reused_maps']) for r in rs),duplicate_seed_starts_avoided=sum(int(r['duplicate_seeds']) for r in rs)))
 lines=['# Seed index port and traditional flood fill follow-up','','## Adopted seed change','','Verified donor checkout experiment/seeded-boundary-events HEADf3547723b79828d9c501182746028e99f7bad116; optimization read from its uncommitted evidence/holonomic/low_magnification_fixed_cost_v30/seed_indexed.cpp. Donor checkout untouched. Target feature/boundary-error-and-discriminant-support HEADa68bca9 plus existing working changes. Only query/selection behavior was transferred; target scanner retains branch/vertex metadata, probe resolution and root/append policies. Full scanner remains its original implementation for calls without selection or dense queries.','','Existing caustic vertex grid and maximum segment length are reused. Query radiusrho+2L+outward roundoff padding bounds both retained curvature-margin vertices and intersecting segments. Candidates sorted by original branch/vertex order; dense selection uses full traversal before probes or roots. This is equivalence to sampled polyline support, not a new continuous-caustic certificate. Geometry/index construction excluded from timings and unchanged.','','## Correctness','','Final provider:7216/7216 inputs have exactly the same hex-float seed coordinates, order, count and support flag. Entire corpus seeded with fresh magnifier per call. Centre roots and cached geometry are supplied/prebuilt before provider timer. No seed-count or root-count reduction is claimed. Seed identity timings on64 representative profile inputs use five alternating batches.','','|profile|seed before us|seed after us|paired median after/before|aggregate after/before|','|---|---:|---:|---:|---:|']
 for g in seed['groups']:lines.append(f"|{g['profile']}|{g['median_before_us']:.2f}|{g['median_after_us']:.2f}|{g['median_paired_ratio']:.3f}|{g['sum_ratio']:.3f}|")
 lines+=['','## Fresh-epoch total cost','','Centre roots + seed generation + adaptive integration included. Initial16, targets1e-3/1e-4, no duplicate scale pass. Magnifier recreated each call; caustic and critical curve built outside timer, seed cache empty. Five alternating batch orders with3 untraced repeats per batch per input. New profiling clocks are disabled in these runs.','','|profile|target|paired median time reduction|aggregate time reduction|count|','|---|---:|---:|---:|---:|']
 for g in full['groups']:lines.append(f"|{g['profile']}|{g['target']}|{100*(1-g['median_paired_ratio']):.1f}%|{100*(1-g['sum_ratio']):.1f}%|{g['count']}|")
 lines+=['','All full numerical records match: flux, met flag, map count and component refinement count; each group accepts31/32 with zero observed false accepts. Existing unresolved case preserved. Provider equality on7216 does not claim a new full14432 integration accuracy campaign.','','## Flood fill results','','Traditional flood fill and8-neighbour topology retained. Existing interval registry already skips reached row spans and duplicate seed starts. Two candidates were implemented and benchmarked: row-shared map constants; compile-time constant uniform weight. Both preserved numerical outputs, but gave no consistent meaningful runtime improvement on five alternating batches. They were reverted; source snapshots and raw results retained. No analytical-edge integration or extra geometric guarantee added.','','Boundary callback diagnostic (nested in fill; include Bennett and row endpoint/error-model work), from saved phase-instrumented binary:','',json.dumps(flood,indent=2),'','Boundary work accounts for~12% uniform/~15% LD of fill. Remaining fill includes mapping, cache insertion, traversal and brightness. fill_queries and new_maps have different scopes: row endpoint models/core validation can query the global cache outside the generic fill counter, so do not subtract them as an exact duplicate count.','', 'Boundary clock is guarded by LCBININT_TRACE_ROW_BOUNDARY; ordinary build has no per-row clock reads. Other counters are collected only undercost_trace. Instrumented source and binary saved as row-boundary-profile.cpp and phase-instrumented.','','## Limits and next step','','Seed typical-point speed improves~9–13% in full fresh-epoch timing; aggregate time improves~2–3% because large initial scans still dominate. Traditional flood fill still needs a larger change in per-cell throughput/storage. Repeated-row caches, row-constant arithmetic and uniform-weight specialization have not shown a gain and should not be reintroduced without new evidence. Full Cartesian/polar scanner callers remain on original traversal unless they use the shared indexed cached seed provider. No global promotion, merge or commit performed.','','Repro scripts: seed_index_port_runner.cpp, seed_index_port_timing.py, seed_index_full_timing.py, seed_index_port_report.py undertests/diagnostics/recal2026. Raw seed equality files, timing batches, phase counters and source snapshots are in this directory.']
 (P/'REPORT.md').write_text('\n'.join(lines)+'\n');(P/'summary.json').write_text(json.dumps(dict(seed_identity_count=len(a),seed_mismatches=mismatches,seed_timing=seed,full_timing=full,flood_profile=flood,flood_candidates_adopted=False),indent=2)+'\n')
 paths=[ROOT/'experiments/boundary-support-overlay/src/lcbinint/magnification/finite_source_magnifier.cpp',ROOT/'experiments/boundary-support-overlay/src/lcbinint/magnification/probe_diagnostics.hpp',ROOT/'experiments/seeded-boundary-events/evidence/holonomic/low_magnification_fixed_cost_v30/seed_indexed.cpp',P/'all-input.tsv',P/'seed-before',P/'seed-final',P/'phase-after',B/'runner-phase-profile']
 (P/'provenance.json').write_text(json.dumps({'target_head':'a68bca9d0e8234ef499dee3d860d23afef6061d1','donor_head':'f3547723b79828d9c501182746028e99f7bad116','donor_uncommitted':True,'threads':1,'initial_bins':16,'sha256':{str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in paths},'timing_omissions':'geometry/index construction, object construction, I/O','retained_policy':'same probes, roots, seed append/support; full scanner preselected for dense queries'},indent=2)+'\n')
if __name__=='__main__':main()
